  const removeAbcDirection = (id: string) => { const next = abcDirections.filter((item) => item.id !== id); setAbcDirections(next); if (abcErrors.length) setAbcErrors(validateAbcProfile(next).errors); };
  const save = () => { const validation = validateAbcProfile(abcDirections); if (!validation.valid) { setAbcErrors(validation.errors); onNotify(validation.errors[0].message); return; } setAbcErrors([]); const next = version + 1; setVersion(next); onNotify(`Профиль вакансии сохранён как версия ${next}`); };
  const errorFor = (directionId: string, field: AbcDirectionField) => abcErrors.find((error) => error.level !== "collection" && error.directionId === directionId && error.field === field);
  const errorId = (directionId: string, field: AbcDirectionField) => `abc-${directionId.replace(/[^a-zA-Z0-9_-]/g, "-")}-${field}-error`;
  const collectionError = abcErrors.find((error) => error.level === "collection");
  return <div className="settings-content"><aside>{sections.map((item) => <button key={item} className={activeRule === item ? "active" : ""} onClick={() => setActiveRule(item)}>{item}<span>›</span></button>)}</aside><section><div className="settings-intro"><div><p className="eyebrow">{vacancy.title} · версия {version}</p><h3>{activeRule}</h3><p>Изменения применяются только к новым запускам после сохранения версии.</p></div></div>{activeRule === "ABC-критерии" ? <div className="abc-direction-editor"><div className="abc-direction-summary"><div><b>Направления оценки</b><p>Наблюдаемые определения A, B и C.</p></div><span>{abcDirections.length}</span></div>{collectionError && <div className="abc-validation-summary" role="alert">{collectionError.message}</div>}<div className="abc-direction-list">{abcDirections.map((direction, index) => { const nameError = errorFor(direction.id, "name"); return <article className="abc-direction-card" key={direction.id}><header><div><span className="direction-order">{index + 1}</span><em>{direction.origin === "standard" ? "Стандартное" : "Добавлено HR"}</em></div><button onClick={() => removeAbcDirection(direction.id)}>Удалить</button></header><label className="direction-name"><span>Название направления</span><input value={direction.name} onChange={(event) => updateDirection(direction.id, "name", event.target.value)} aria-invalid={Boolean(nameError)} aria-describedby={nameError ? errorId(direction.id, "name") : undefined} />{nameError && <span className="abc-field-error" id={errorId(direction.id, "name")} role="alert">{nameError.message}</span>}</label><div className="abc-grade-grid">{(["A", "B", "C"] as const).map((grade) => { const field = `grade${grade}` as "gradeA" | "gradeB" | "gradeC"; const fieldError = errorFor(direction.id, field); return <label key={grade}><span className={`grade-mark grade-${grade.toLowerCase()}`}>{grade}</span><textarea value={direction[field]} onChange={(event) => updateDirection(direction.id, field, event.target.value)} aria-invalid={Boolean(fieldError)} aria-describedby={fieldError ? errorId(direction.id, field) : undefined} />{fieldError && <span className="abc-field-error" id={errorId(direction.id, field)} role="alert">{fieldError.message}</span>}</label>; })}</div></article>; })}</div>{abcDirections.length === 0 && <div className="abc-empty-state"><b>Направлений пока нет</b></div>}<div className="settings-actions"><button className="secondary-button" onClick={() => setAbcDirections(createStandardAbcDirections())}>Сбросить настройки</button><button className="secondary-button" onClick={() => setAbcDirections((items) => [...items, { id: `custom-${Date.now()}`, name: "Новое направление", gradeA: "", gradeB: "", gradeC: "", origin: "custom" }])}>＋ Добавить направление</button><button className="save-button" onClick={save}>Сохранить новую версию</button></div></div> : <><label className="settings-field"><span>Правила и наблюдаемые признаки</span><textarea wrap="soft" value={values[activeRule] ?? ""} onChange={(event) => setValues((current) => ({ ...current, [activeRule]: event.target.value }))} rows={10} /></label><div className="settings-actions"><button className="save-button" onClick={save}>Сохранить новую версию</button></div></>}</section></div>;
}

type GeneratedCreationProfile = {
  schemaVersion: string;
  templateVersion: string;
  profile: Record<string, string>;
  abcDirections: AbcProfileDirection[];
  hrDecisionMarkers: string[];
};

function stableCreationJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableCreationJson).join(",")}]`;
  if (value && typeof value === "object") return `{${Object.entries(value as Record<string, unknown>).sort(([a], [b]) => a.localeCompare(b)).map(([key, item]) => `${JSON.stringify(key)}:${stableCreationJson(item)}`).join(",")}}`;
  return JSON.stringify(value);
}

async function creationSnapshotHash(title: string, generated: GeneratedCreationProfile) {
  const bytes = new TextEncoder().encode(stableCreationJson({
    title: title.trim().replace(/\s+/g, " "),
    profile: generated.profile,
    abcDirections: generated.abcDirections,
    templateVersion: generated.templateVersion,
  }));
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return `sha256:${[...new Uint8Array(digest)].map((item) => item.toString(16).padStart(2, "0")).join("")}`;
}

